validator:
function validate(input) {
  const [{ DailySales = [] }] = input;
  for (const [date, make, lead, partner] of DailySales) {
    if (date === null || make === null || lead === null || partner === null) return 'DailySales rows may not contain null.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `date_id ${date} is not a YYYY-MM-DD date.`;
    if (!/^[a-z]+$/.test(make)) return `make_name ${make} must be lowercase letters.`;
    if (lead < 0 || partner < 0) return 'lead_id and partner_id may not be negative.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (n) => Math.floor(rand() * n);
  const makes = small ? ['toyota', 'honda', 'bmw'] : ['toyota', 'honda', 'bmw', 'audi', 'ford', 'kia', 'mazda', 'tesla', 'volvo', 'fiat'];
  const days = small ? 3 : 30;
  const ids = small ? 4 : 60;
  const rows = small ? pick(9) : 2000;
  const DailySales = [];
  for (let k = 0; k < rows; k++) {
    // Small cases sometimes repeat the previous row, since duplicates are allowed.
    if (small && DailySales.length > 0 && rand() < 0.2) { DailySales.push(DailySales[DailySales.length - 1].slice()); continue; }
    const date = `2020-12-${String(1 + pick(days)).padStart(2, '0')}`;
    DailySales.push([date, makes[pick(makes.length)], pick(ids), pick(ids)]);
  }
  return [{ DailySales }];
}
